// advanced-hunting tables into Sentinel; Timestamp → TimeGenerated).
let fifaDomains = dynamic(["www-fifa.me","www-fifa.co","26-fifa.com","shop-26fifa.com","op.shop-26fifa.com","fifaofficialstore.shop","fifa2026guess.com","fortune-worldcup2026.com.cn"]);
let urlMsgs = EmailUrlInfo
    | where TimeGenerated > ago(30d)
    | where UrlDomain has_any (fifaDomains) or Url has_any (fifaDomains)
    | distinct NetworkMessageId;
EmailEvents
| where TimeGenerated > ago(30d)
| where EmailDirection == "Inbound"
| where SenderFromDomain has_any (fifaDomains)
     or SenderMailFromDomain has_any (fifaDomains)
     or NetworkMessageId in (urlMsgs)
| project TimeGenerated, NetworkMessageId, SenderFromAddress, SenderMailFromAddress, SenderFromDomain, RecipientEmailAddress, Subject, DeliveryAction, DeliveryLocation
| order by TimeGenerated desc

